import React, { useState } from 'react'
import AdminFrame from '../../../components/management/AdminFrame.jsx'
import { useCatalogResource } from '../../../hooks/useCatalogResource.js'
import { useAuth } from '../../../context/useAuth.js'
import { adminManagementService, loadAdminPlans, PLAN_STATUSES } from '../../../services/adminManagementService.js'
import { formatSubscriptionMoney } from '../../../services/subscriptionModels.js'
import { ApiState, ApiErrorMessage, inputClass, buttonClass, panelClass } from '../../../components/management/ApiState.jsx'
export function AdminPlanForm({ plan, busy, onSave, onClose }) {
  const [values, setValues] = useState(() => ({ ...(plan || { code: '', name: '', description: '', monthlyPrice: '', currency: 'VND', billingPeriodMonths: 1, status: 'INACTIVE' }), featureRows: Object.entries(plan?.features || {}).map(([code, value]) => ({ code, value })) })), [confirmed, setConfirmed] = useState(false)
  const field = (key) => ({ value: values[key] ?? '', onChange: (event) => setValues((current) => ({ ...current, [key]: event.target.value })) })
  return <form className={panelClass} onSubmit={(event) => { event.preventDefault(); if (confirmed) onSave(values) }}><h2 className="font-bold">{plan ? 'Sửa gói' : 'Tạo gói dịch vụ'}</h2><fieldset disabled={busy} className="grid gap-3 sm:grid-cols-2">
    <label>Mã gói<input required maxLength={50} {...field('code')} className={inputClass} /></label><label>Tên gói<input required maxLength={120} {...field('name')} className={inputClass} /></label><label>Giá theo tháng<input required type="number" min="0" step="0.01" {...field('monthlyPrice')} className={inputClass} /></label><label>Chu kỳ (tháng)<input required type="number" min="1" step="1" {...field('billingPeriodMonths')} className={inputClass} /></label><label>Tiền tệ<input readOnly value="VND" className={inputClass} /></label><label>Trạng thái<select {...field('status')} className={inputClass}>{PLAN_STATUSES.map((status) => <option key={status}>{status}</option>)}</select></label><label className="sm:col-span-2">Mô tả<textarea {...field('description')} className={inputClass} /></label>
    <section className="space-y-3 sm:col-span-2"><h3 className="font-bold">Tính năng</h3>{values.featureRows.map((row, index) => <div key={index} className="grid gap-3 sm:grid-cols-3"><label>Mã tính năng<input required maxLength={80} value={row.code} onChange={(event) => setValues((current) => ({ ...current, featureRows: current.featureRows.map((item, i) => i === index ? { ...item, code: event.target.value } : item) }))} className={inputClass} /></label><label>Giá trị (chuỗi)<input required maxLength={255} value={row.value} onChange={(event) => setValues((current) => ({ ...current, featureRows: current.featureRows.map((item, i) => i === index ? { ...item, value: event.target.value } : item) }))} className={inputClass} /></label><button type="button" className="underline" onClick={() => setValues((current) => ({ ...current, featureRows: current.featureRows.filter((_, i) => i !== index) }))}>Bỏ tính năng</button></div>)}<button type="button" className="underline" onClick={() => setValues((current) => ({ ...current, featureRows: [...current.featureRows, { code: '', value: '' }] }))}>Thêm tính năng</button></section>
    <p className="text-sm sm:col-span-2">Backend không cho đổi mã gói đã có đơn mua. Thay đổi gói không sửa snapshot của kỳ/đơn đã mua.</p><label className="flex gap-2 sm:col-span-2"><input type="checkbox" checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} />Xác nhận lưu các trường và thay toàn bộ cấu hình tính năng trên.</label><button disabled={!confirmed} className={buttonClass}>Lưu gói</button><button type="button" className="underline" onClick={onClose}>Đóng</button>
  </fieldset></form>
}
export default function AdminPlansPage({ onNavigate }) {
  const { roles } = useAuth(), resource = useCatalogResource(loadAdminPlans)
  const [selected, setSelected] = useState(null), [adding, setAdding] = useState(false), [busy, setBusy] = useState(false), [error, setError] = useState(null), [confirmed, setConfirmed] = useState(''), [notice, setNotice] = useState('')
  async function mutate(action) { if (busy || !roles.includes('ADMIN')) return; setBusy(true); setError(null); setNotice(''); try { await action(); setSelected(null); setAdding(false); setConfirmed(''); setNotice('Backend đã xác nhận, danh sách được tải lại.'); resource.reload() } catch (failure) { setError(failure); if (![400, 422].includes(failure.status)) resource.reload() } finally { setBusy(false) } }
  return <AdminFrame title="Quản lý gói dịch vụ" activeTab="admin-plans" onNavigate={onNavigate}><section className={panelClass}><div className="flex flex-wrap gap-3"><button disabled={busy || !roles.includes('ADMIN')} className={buttonClass} onClick={() => { setAdding(true); setSelected(null) }}>Tạo gói mới</button><button className="underline" onClick={resource.reload}>Tải lại gói</button></div><ApiState resource={resource}>{resource.data && (resource.data.length ? <div className="grid gap-4 lg:grid-cols-2">{resource.data.map((plan) => <article key={plan.id} className="space-y-3 rounded-xl border p-4"><h2 className="font-bold">{plan.code} · {plan.name}</h2><p>{formatSubscriptionMoney(plan.monthlyPrice, plan.currency)} · {plan.billingPeriodMonths} tháng · {plan.status}</p><p>{plan.description}</p><button disabled={busy || !roles.includes('ADMIN')} className={buttonClass} onClick={() => { setSelected(plan); setAdding(false) }}>Sửa gói</button>{plan.status !== 'ARCHIVED' && <div className="flex flex-wrap gap-3"><label className="flex gap-2"><input type="checkbox" disabled={busy} checked={confirmed === plan.id} onChange={(event) => setConfirmed(event.target.checked ? plan.id : '')} />Xác nhận archive, không hủy kỳ đã mua</label><button disabled={busy || confirmed !== plan.id || !roles.includes('ADMIN')} onClick={() => mutate(() => adminManagementService.archivePlan(plan.id))} className="underline disabled:opacity-40">Archive gói</button></div>}</article>)}</div> : <p>Chưa có gói dịch vụ trong backend.</p>)}</ApiState></section>{(adding || selected) && roles.includes('ADMIN') && <AdminPlanForm key={selected?.id || 'new'} plan={selected} busy={busy} onClose={() => { setAdding(false); setSelected(null) }} onSave={(input) => mutate(() => adminManagementService.savePlan(selected?.id, input))} />}{error && <ApiErrorMessage error={error} />}{notice && <p role="status">{notice}</p>}</AdminFrame>
}

